-- One-time seed: loads the current hardcoded menu (src/stores/products.ts) into
-- the real products table. Run this once, after 0001_init.sql, in the SQL Editor.

insert into public.products
  (id, name, description, price, original_price, category, scent_type, stock, low_stock_threshold, gradient, accent, image, rating, reviews, featured, is_new, seasonal)
overriding system value
values
  (1, 'Espresso', 'Pure and intense. A double shot of premium single-origin espresso, crafted for those who love bold, concentrated flavour.', 3.5, NULL, 'Hot Coffee', 'Bold & Intense', 80, 20, 'linear-gradient(145deg,#2c1008,#4a1e0a)', '#c8813a', 'https://images.unsplash.com/photo-1596952954288-16862b37b44b?w=600&fit=crop&auto=format&q=85', 4.9, 2134, true, false, false),
  (2, 'Cappuccino', 'Balanced and velvety. Equal parts espresso, steamed milk, and rich foam — a classic Italian favourite done to perfection.', 4.5, NULL, 'Hot Coffee', 'Rich & Creamy', 65, 15, 'linear-gradient(145deg,#7c3a1e,#c87941)', '#f0c27f', 'https://images.unsplash.com/photo-1541167760496-1628856ab772?w=600&fit=crop&auto=format&q=85', 4.8, 1876, true, false, false),
  (3, 'Caffe Latte', 'Smooth and comforting. A generous pour of steamed milk over a double espresso base, with just a touch of delicate foam on top.', 4.75, NULL, 'Hot Coffee', 'Smooth & Milky', 70, 15, 'linear-gradient(145deg,#c8956c,#f5e6d3)', '#8B4513', 'https://images.unsplash.com/photo-1570968915860-54d5d301fa13?w=600&fit=crop&auto=format&q=85', 4.7, 2567, true, false, false),
  (4, 'Americano', 'Clean and bold. Espresso shots pulled long with hot water — a straightforward cup that highlights the depth of our coffee beans.', 3.75, NULL, 'Hot Coffee', 'Clean & Bold', 90, 20, 'linear-gradient(145deg,#1a0a04,#3d1c08)', '#d4a060', 'https://images.unsplash.com/photo-1481627834876-b7833e8f5570?w=600&fit=crop&auto=format&q=85', 4.6, 987, false, false, false),
  (5, 'Cold Brew', 'Steeped for 18 hours. Our cold brew is smooth, naturally sweet, and low in acidity — served over ice for the perfect slow coffee experience.', 5, NULL, 'Cold Coffee', 'Smooth & Sweet', 40, 10, 'linear-gradient(145deg,#0d0704,#2c1810)', '#a0522d', 'https://images.unsplash.com/photo-1517959105821-eae173431639?w=600&fit=crop&auto=format&q=85', 4.8, 1432, false, false, false),
  (6, 'Caramel Macchiato', 'Layers of indulgence. Vanilla-infused milk topped with espresso and a golden caramel drizzle — sweet, strong, and utterly satisfying.', 5.5, 6.5, 'Specialty', 'Sweet & Caramel', 35, 10, 'linear-gradient(145deg,#f0a940,#c8813a)', '#8B4513', 'https://images.unsplash.com/photo-1485808191679-5f86510bd3e0?w=600&fit=crop&auto=format&q=85', 4.9, 3241, false, false, false),
  (7, 'Mocha', 'Coffee meets chocolate. Rich espresso blended with dark chocolate sauce and steamed milk, crowned with a cloud of whipped cream.', 5.25, NULL, 'Hot Coffee', 'Chocolatey', 50, 12, 'linear-gradient(145deg,#3d1c08,#6b3a2a)', '#d4a060', 'https://images.unsplash.com/photo-1572442388796-11668a67e53d?w=600&fit=crop&auto=format&q=85', 4.7, 1654, false, false, false),
  (8, 'Flat White', 'Espresso forward. A ristretto-based drink with velvety microfoam milk — stronger than a latte, smoother than a cappuccino.', 4.5, NULL, 'Hot Coffee', 'Velvety & Strong', 60, 15, 'linear-gradient(145deg,#fdf6ec,#f5e6d3)', '#8B4513', 'https://images.unsplash.com/photo-1527018601521-77acd16e2b15?w=600&fit=crop&auto=format&q=85', 4.6, 876, false, false, false),
  (9, 'Iced Latte', 'Cool and refreshing. A double espresso poured over fresh ice and cold milk — the perfect pick-me-up on a warm day.', 5, NULL, 'Cold Coffee', 'Refreshing & Cool', 55, 12, 'linear-gradient(145deg,#dbeafe,#bfdbfe)', '#6b3a2a', 'https://images.unsplash.com/photo-1497636577773-f1231844b336?w=600&fit=crop&auto=format&q=85', 4.7, 2098, false, true, true),
  (10, 'Matcha Latte', 'Earthy and vibrant. Premium ceremonial-grade matcha whisked smooth with oat milk — an energising alternative with a natural green glow.', 5.25, NULL, 'Specialty', 'Earthy & Vibrant', 28, 8, 'linear-gradient(145deg,#d1fae5,#6ee7b7)', '#065f46', 'https://images.unsplash.com/photo-1556679343-c7306c1976bc?w=600&fit=crop&auto=format&q=85', 4.5, 1120, false, true, true),
  (11, 'Vanilla Latte', 'Warm and fragrant. Silky steamed milk, house-made vanilla syrup, and a rich espresso base — comfort in every sip.', 5, NULL, 'Hot Coffee', 'Warm & Fragrant', 45, 10, 'linear-gradient(145deg,#fef3c7,#fde68a)', '#92400e', 'https://images.unsplash.com/photo-1572715376701-98568319fd0b?w=600&fit=crop&auto=format&q=85', 4.7, 1789, false, false, false),
  (12, 'Cortado', 'Equal and balanced. A small but mighty equal-parts espresso and steamed milk — no foam, no fuss. Just pure coffee harmony.', 4, NULL, 'Hot Coffee', 'Balanced & Pure', 30, 8, 'linear-gradient(145deg,#78350f,#d97706)', '#fbbf24', 'https://images.unsplash.com/photo-1513530534585-c7b1394c6d51?w=600&fit=crop&auto=format&q=85', 4.8, 765, false, false, false),
  (13, 'Classic Scone', 'A warm, golden British scone served with velvety clotted cream and rich strawberry jam — the crown jewel of London afternoon tea.', 3.5, NULL, 'Sweets & Cakes', 'Buttery & Classic', 30, 8, 'linear-gradient(145deg,#fef3c7,#fde68a)', '#d4a040', 'https://images.unsplash.com/photo-1555507036-ab1f4038808a?w=600&fit=crop&auto=format&q=85', 4.8, 892, false, true, false),
  (14, 'Victoria Sponge', 'Britain''s most beloved cake. Two light golden sponge layers filled with fresh cream and raspberry jam, finished with a dusting of icing sugar.', 4.5, NULL, 'Sweets & Cakes', 'Light & Airy', 20, 6, 'linear-gradient(145deg,#fef9c3,#fde68a)', '#f5c200', 'https://images.unsplash.com/photo-1464349095431-e9a21285b19c?w=600&fit=crop&auto=format&q=85', 4.9, 1240, false, false, false),
  (15, 'Lemon Drizzle Cake', 'Zesty and irresistible. A moist almond sponge drenched in sharp lemon glaze — the UK''s most ordered café cake, beloved slice after slice.', 4, NULL, 'Sweets & Cakes', 'Citrusy & Bright', 18, 5, 'linear-gradient(145deg,#fef9c3,#fde047)', '#f5c200', 'https://images.unsplash.com/photo-1571115177098-24ec42ed204d?w=600&fit=crop&auto=format&q=85', 4.8, 2103, true, false, false),
  (16, 'Carrot Cake', 'Warmly spiced with cinnamon and nutmeg, packed with fresh carrot and walnuts, crowned with a thick layer of smooth cream cheese frosting.', 4.5, NULL, 'Sweets & Cakes', 'Spiced & Wholesome', 15, 5, 'linear-gradient(145deg,#fde68a,#f59e0b)', '#d97706', 'https://images.unsplash.com/photo-1621303837174-89787a7d4729?w=600&fit=crop&auto=format&q=85', 4.7, 876, false, false, false),
  (17, 'Chocolate Brownie', 'Dense, fudgy, and intensely chocolatey. Crisp crackle on top, gooey in the middle — a London café staple that never goes out of style.', 3.75, NULL, 'Sweets & Cakes', 'Fudgy & Rich', 25, 8, 'linear-gradient(145deg,#3d1c08,#6b3a2a)', '#d4a060', 'https://images.unsplash.com/photo-1606313564200-e75d5e3d7343?w=600&fit=crop&auto=format&q=85', 4.9, 3421, false, false, false),
  (18, 'Millionaire''s Shortbread', 'Three layers of pure indulgence: crumbly Scottish shortbread, thick salted caramel, and a dark chocolate top with a white chocolate drizzle.', 3.5, NULL, 'Sweets & Cakes', 'Caramel & Shortbread', 22, 6, 'linear-gradient(145deg,#f0a820,#c07810)', '#f5c200', 'https://images.unsplash.com/photo-1558326567-98ae2405596b?w=600&fit=crop&auto=format&q=85', 4.9, 1876, false, false, false),
  (19, 'Biscoff Cheesecake', 'The UK''s most talked-about café dessert. Creamy no-bake cheesecake on a Lotus biscuit base, topped with silky Biscoff spread and a whole cookie.', 5.5, NULL, 'Sweets & Cakes', 'Creamy & Caramelised', 12, 4, 'linear-gradient(145deg,#d4841c,#8b5e3c)', '#d4841c', 'https://images.unsplash.com/photo-1533134242443-d4fd215305ad?w=600&fit=crop&auto=format&q=85', 5, 4102, false, true, true),
  (20, 'Cinnamon Roll', 'Freshly baked daily. Soft and pillowy with layers of warm cinnamon sugar, finished with a generous drizzle of vanilla cream cheese icing.', 4, NULL, 'Sweets & Cakes', 'Warm & Spiced', 18, 5, 'linear-gradient(145deg,#fde68a,#d4a040)', '#d4a040', 'https://images.unsplash.com/photo-1509365465985-25d11c17e812?w=600&fit=crop&auto=format&q=85', 4.8, 1543, true, false, false),
  (21, 'Sticky Toffee Pudding', 'Warm dense date sponge drenched in rich, buttery toffee sauce — Britain''s ultimate comfort dessert, served warm and heavenly.', 5, NULL, 'Sweets & Cakes', 'Warm & Toffee', 14, 4, 'linear-gradient(145deg,#3d1c08,#78350f)', '#f0a820', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=600&fit=crop&auto=format&q=85', 4.9, 2876, false, false, false),
  (22, 'Banoffee Pie', 'A British invention loved worldwide. Buttery biscuit base, thick dulce de leche, fresh banana slices and a generous cloud of softly whipped cream.', 5, NULL, 'Sweets & Cakes', 'Banana & Toffee', 12, 4, 'linear-gradient(145deg,#fef3c7,#fde68a)', '#f5c200', 'https://images.unsplash.com/photo-1565958011703-44f9829ba187?w=600&fit=crop&auto=format&q=85', 4.8, 1654, false, false, false),
  (23, 'Eton Mess', 'A glorious British mess of crushed meringue, fresh strawberries and softly whipped cream — light, fruity and perfectly indulgent.', 4.5, NULL, 'Sweets & Cakes', 'Fresh & Fruity', 10, 3, 'linear-gradient(145deg,#fce7f3,#fbcfe8)', '#ec4899', 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=600&fit=crop&auto=format&q=85', 4.7, 987, false, true, true),
  (24, 'Jam Doughnut', 'A British bakery icon. Pillowy soft dough fried golden, rolled in caster sugar and bursting with sweet strawberry jam — a timeless treat.', 2.75, NULL, 'Sweets & Cakes', 'Sweet & Pillowy', 35, 10, 'linear-gradient(145deg,#fde68a,#f59e0b)', '#dc2626', 'https://images.unsplash.com/photo-1499636136210-6f4ee915583e?w=600&fit=crop&auto=format&q=85', 4.6, 3102, false, false, false),
  (25, 'Chocolate Éclair', 'Elegant choux pastry piped with Chantilly cream and topped with a glossy dark chocolate glaze — a French-British café favourite.', 4, NULL, 'Sweets & Cakes', 'Elegant & Chocolatey', 16, 5, 'linear-gradient(145deg,#3d1c08,#6b3a2a)', '#d4a060', 'https://images.unsplash.com/photo-1551892374-ecf8754cf8b0?w=600&fit=crop&auto=format&q=85', 4.8, 1432, false, false, false),
  (26, 'Battenberg Cake', 'The iconic Victorian checkerboard cake — pink and yellow almond sponge wrapped in sweet marzipan. A British teatime tradition since 1884.', 4.25, NULL, 'Sweets & Cakes', 'Marzipan & Vanilla', 14, 4, 'linear-gradient(145deg,#fbcfe8,#fce7f3)', '#ec4899', 'https://images.unsplash.com/photo-1609525313270-e61254f2f0b2?w=600&fit=crop&auto=format&q=85', 4.7, 765, false, false, false),
  (27, 'Treacle Tart', 'Harry Potter''s favourite pudding. Golden syrup and fresh breadcrumbs baked in a crisp shortcrust pastry with a classic lattice top. Served warm.', 4.5, NULL, 'Sweets & Cakes', 'Golden & Sticky', 12, 4, 'linear-gradient(145deg,#fef3c7,#f59e0b)', '#d97706', 'https://images.unsplash.com/photo-1535920527002-b35e96722eb9?w=600&fit=crop&auto=format&q=85', 4.8, 1098, false, false, false),
  (28, 'Chelsea Bun', 'London''s very own spiral bun. Soft enriched dough rolled with cinnamon, plump raisins and mixed peel, glazed with sticky golden syrup.', 3.25, NULL, 'Sweets & Cakes', 'Spiced & Fruity', 20, 6, 'linear-gradient(145deg,#fde68a,#c8a030)', '#d97706', 'https://images.unsplash.com/photo-1549931319-a545dcf3bc7c?w=600&fit=crop&auto=format&q=85', 4.7, 876, false, false, false);

-- keep the identity sequence in sync with the explicit ids inserted above
select setval(pg_get_serial_sequence('public.products', 'id'), (select max(id) from public.products));
